Generic Types
Type Parameters
// TypeScript
function identity<T>(x: T): T { return x; }

// C#
public static T identity<T>(T x) { return x; }
Generic Classes
// TypeScript
class Box<T> {
  constructor(private value: T) {}
  get(): T { return this.value; }
}

// C#
public class Box<T>
{
    private T value;
    public Box(T value) { this.value = value; }
    public T get() { return value; }
