Symbol Table
Symbol Tracking
symbol-table/:
type SymbolEntry = {
  name: string;
  kind: "variable" | "function" | "class" | "interface" | "type";
  type?: IrType;
  exported: boolean;
};

type SymbolTable = {
  entries: Map<string, SymbolEntry>;
  parent?: SymbolTable;
};
Symbol Resolution
const resolveSymbol = (
  name: string,
  table: SymbolTable
): SymbolEntry | undefined => {
  const entry = table.entries.get(name);
  if (entry) return entry;
  if (table.parent) return resolveSymbol(name, table.parent);
  return undefined;
};
